package ama.storage;
import java.nio.file.*;import java.nio.file.attribute.PosixFilePermissions;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class Task11KnowledgeReopenGuardTest {
 @TempDir Path temp;final Map<String,Object> ids=Map.of("providerId","provider","storeInstanceId","store","clientId","client","delegationKeyId","delegation","assertionKeyId","assertion");
 Path ready()throws Exception {var root=Files.createDirectory(temp.resolve("knowledge"));var runtime=Files.createDirectory(root.resolve("runtime"));for(var path:List.of(root,runtime))Files.setPosixFilePermissions(path,PosixFilePermissions.fromString("rwx------"));write(runtime.resolve("knowledge.sqlite"),"not read as SQLite");endpoint(root,12345,ids);return root;}
 void write(Path p,String value)throws Exception{Files.writeString(p,value);Files.setPosixFilePermissions(p,PosixFilePermissions.fromString("rw-------"));}
 void endpoint(Path root,int port,Map<String,Object> identities)throws Exception{write(root.resolve("runtime/endpoint.json"),new ObjectMapper().writeValueAsString(Map.of("port",port,"store",root.resolve("runtime/knowledge.sqlite").toString(),"identities",identities)));}
 @Test void exactMetadataPassesWithoutReadingDatabaseContent()throws Exception{var root=ready();assertDoesNotThrow(()->Task11KnowledgeFixture.requireReopen(root,12345,ids));assertEquals("not read as SQLite",Files.readString(root.resolve("runtime/knowledge.sqlite")));}
 @Test void absentStoreFailsBeforeConstructorFallback()throws Exception{var root=ready();Files.delete(root.resolve("runtime/knowledge.sqlite"));assertThrows(AssertionError.class,()->Task11KnowledgeFixture.reopenOnly(temp,"owner",root,12345,ids));try(var paths=Files.list(root.resolve("runtime"))){assertEquals(List.of("endpoint.json"),paths.map(p->p.getFileName().toString()).toList());}}
 @Test void absentEndpointFailsWithoutCreatingOne()throws Exception{var root=ready();Files.delete(root.resolve("runtime/endpoint.json"));assertThrows(AssertionError.class,()->Task11KnowledgeFixture.reopenOnly(temp,"owner",root,12345,ids));assertFalse(Files.exists(root.resolve("runtime/endpoint.json")));}
 @Test void absentBothFailWithoutInitializer()throws Exception{var root=ready();Files.delete(root.resolve("runtime/endpoint.json"));Files.delete(root.resolve("runtime/knowledge.sqlite"));assertThrows(AssertionError.class,()->Task11KnowledgeFixture.reopenOnly(temp,"owner",root,12345,ids));try(var paths=Files.list(root.resolve("runtime"))){assertEquals(0,paths.count());}}
 @Test void mismatchedPortAndIdentitiesFail()throws Exception{var root=ready();assertThrows(AssertionError.class,()->Task11KnowledgeFixture.requireReopen(root,12346,ids));endpoint(root,12345,Map.of("providerId","changed"));assertThrows(AssertionError.class,()->Task11KnowledgeFixture.requireReopen(root,12345,ids));}
 @Test void symlinkStoreFails()throws Exception{var root=ready();Path file=root.resolve("runtime/knowledge.sqlite");Files.delete(file);Path outside=temp.resolve("other");write(outside,"not database");Files.createSymbolicLink(file,outside);assertThrows(AssertionError.class,()->Task11KnowledgeFixture.requireReopen(root,12345,ids));}
}
